mapper.select:
SELECT id, report_type AS type, report_title AS title, report_period_start AS period_start, report_period_end AS period_end, report_status AS status, generated_at, data_latest_time, freshness_status, raw_record_count, unique_problem_count, generation_source, validation_status, degraded, scope_snapshot, JSON_EXTRACT(facts_snapshot, '$.overviewMetrics') AS overview_metrics FROM t_ai_report WHERE is_deleted = 0 AND report_type = #{type}
AND (generated_at < #{beforeTime} OR (generated_at = #{beforeTime} AND id < #{beforeId}))
ORDER BY generated_at DESC, id DESC LIMIT #{limit}
